# [0093/1298] clausewitz_vol2_1_en.mp3
if [ ! -f "$AUDIO_DIR/clausewitz_vol2_1_en.mp3" ]; then
  echo "[0093/1298] Generating: clausewitz_vol2_1_en.mp3"
  curl -s -X POST \
