# [1189/1298] thucydides_v1_2_en.mp3
if [ ! -f "$AUDIO_DIR/thucydides_v1_2_en.mp3" ]; then
  echo "[1189/1298] Generating: thucydides_v1_2_en.mp3"
  curl -s -X POST \
